// Turns the stylesheet of every demo website into a string the website builder can inline.
// The bot's templates (src/sites/families) are the demo designs: they use the same class names
// and the same CSS, so a change to a demo's stylesheet reaches the template after running
//   node scripts/family-css.mjs
// A unit test fails when the generated files are out of date.
import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const demos = join(root, "src/app/(demos)/demos");
const out = join(root, "src/sites/families/css");

export function minify(css) {
  return css
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/\s+/g, " ")
    .replace(/\s*([{};])\s*/g, "$1")
    .replace(/,\s+/g, ",")
    .replace(/;}/g, "}")
    .trim();
}
const file = (name, css, from) => `// Generated by scripts/family-css.mjs from ${from}. Do not edit.\nexport const ${name} = ${JSON.stringify(css)};\n`;

export function build() {
  const files = new Map();
  // The shared demo kit, without the floating HOPI bar: a generated site has its own notice.
  const kit = readFileSync(join(root, "src/demos/kit.css"), "utf8").split("/* ── The HOPI bar ── */")[0];
  files.set("kit.ts", file("KIT_CSS", minify(kit), "src/demos/kit.css"));
  for (const slug of readdirSync(demos).sort()) {
    const css = readFileSync(join(demos, slug, "style.css"), "utf8");
    files.set(`${slug}.ts`, file("CSS", minify(css), `src/app/(demos)/demos/${slug}/style.css`));
  }
  return files;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  mkdirSync(out, { recursive: true });
  for (const [name, content] of build()) writeFileSync(join(out, name), content);
  console.log(`Wrote ${build().size} stylesheets to src/sites/families/css`);
}
